const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const heartbeat = $input.first().json;
const reportRelativePath = `heartbeat/${new Date().toISOString().replace(/[:]/g, '-')}.json`;
const reportResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: JSON.stringify(heartbeat, null, 2) }),
});
if (!reportResponse.ok) {
  const body = await reportResponse.text();
  throw new Error(`reports/write failed: ${reportResponse.status} ${body}`);
}
const contextResponse = await fetch(`${runnerBase}/context/heartbeat`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { ...heartbeat, reportRelativePath } }),
});
if (!contextResponse.ok) {
  const body = await contextResponse.text();
  throw new Error(`context/heartbeat failed: ${contextResponse.status} ${body}`);
}
return [{ json: { ...heartbeat, reportRelativePath } }];
